import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Lower the while state fold to Loop + explicit protocol ops","description":"","frontmatter":{"title":"Lower the `while` state fold to `Loop` + explicit protocol ops","type":"adr","date":"2026-10-17T00:00:00.000Z","status":"accepted","status_note":"Accepted — implemented; pilot for retiring the \\"non-input position\\"\\ndecline class."},"headers":[],"relativePath":"handl/project/adrs/0147-lowering-state-fold-while.md","filePath":"vendored/handl/project/adrs/0147-lowering-state-fold-while.md"}'),a={name:`handl/project/adrs/0147-lowering-state-fold-while.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0147-lower-the-while-state-fold-to-loop-explicit-protocol-ops" tabindex="-1">ADR-0147: Lower the <code>while</code> state fold to <code>Loop</code> + explicit protocol ops <a class="header-anchor" href="#adr-0147-lower-the-while-state-fold-to-loop-explicit-protocol-ops" aria-label="Permalink to “ADR-0147: Lower the while state fold to Loop + explicit protocol ops”">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p><code>handl-kit-arrow-lower</code> instantiates a node&#39;s <code>lang.eval</code> scheme by substituting <code>proj_child</code>/<code>proj_rest</code>/<code>Child</code> placeholders with the node&#39;s lowered children. A placeholder is only honest where the position receives the <em>node&#39;s own input</em>: in the env-based engines a placeholder re-evaluates the AST child in the ambient env and ignores its incoming value, while a lowered child is an arrow that consumes its input. Positions fed a computed value — <code>Seq.snd</code>, <code>Choice</code> arms, <code>Loop.body</code>, <code>First</code>, <code>App</code> args — therefore decline, and the runtime falls back to AST eval.</p><p><code>eval.while</code> is <code>Seq[proj_child 0, Loop[loop_step(proj_child 1)]]</code>: the step placeholder sits in <code>Loop.body</code>. <code>while</code> is the dominant control construct of the arrow dialect (the <code>concurrent-epoll</code> scheduler, HTTP server, codec and client packages fold state with it — ~40 sites), so the decline kept every one of those functions on the interpreter.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Lower <code>while</code> in <code>handl-kit-arrow-lower::lower_while</code> (the <code>lower_if</code>/ <code>lower_loop</code> precedent: per-kind arms for constructs whose schemes are env-engine-shaped):</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>while init { step }   →   Seq[ init , Loop[ body ] ]</span></span></code></pre></div><p><code>Loop</code>&#39;s body runs on the <code>[in, st]</code> pair (a 2-array — <code>proj_child</code> projects it). <code>body</code> reproduces the <code>loop_step</code> protocol in combinators:</p><ol><li><strong>current</strong> = <code>st == null ? in : st</code>, expressed as <code>product(eq(proj_child 1, null), id) &gt;&gt;&gt; pair_tag &gt;&gt;&gt; Choice(proj_child 0, proj_child 1)</code> — <code>pair_tag</code> turns <code>[cond, pair]</code> into <code>Either pair</code>, so the chosen arm still sees the pair and projects <code>in</code>/<code>st</code>.</li><li>The step arrow applies to <code>current</code> destructured <strong>by param name</strong> (<code>array[field_access p0, field_access p1, …]</code> for multi-param steps; <code>id</code> for a single param) — the <code>build_loop_step_args</code> contract.</li><li>A new <code>loop_outcome</code> op maps the step result: <code>{state: v}</code> → <code>right(v)</code> (continue), <code>{out: v}</code> → <code>left(v)</code> (terminate), bare <code>v</code> → <code>left(v)</code> — exactly <code>loop_step_outcome</code> in <code>plugin-engine-exec</code>. It is implemented in both <code>plugin-engine</code>&#39;s term interpreter and <code>apply_native</code>, so the emitted term keeps its meaning whether it runs on the arrow interpreter or embedded in a <code>__term__</code>/handler term under the tree-walk.</li></ol><p>A step that captures enclosing parameters (e.g. the predicate <code>p</code> in <code>drop_where</code>) lowers to a <code>{__term__, __bound__}</code> bound-record producer whose <code>__bound__</code> positions project the <em>enclosing</em> input. Under <code>Loop</code> the incoming is <code>[in, st]</code>, not the enclosing input — so the producer is hoisted: <code>Seq[ product(init, step), Loop[body&#39;] ]</code>, and <code>body&#39;</code> applies the materialized record (<code>App</code>) to the name-destructured state. This is the same hoist <code>lower_loop</code> already uses for its record-producing steps.</p><p>Steps that are not function literals decline to the AST fallback, as before — the scheme is unchanged for the env engines.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><code>while</code> folds compile to the variable-free calculus; the printed &quot;falling back to AST eval&quot; declines in the arrow suites drop to zero (<code>ws-c</code> had 3, all <code>while</code>).</li><li><code>eval.while</code> stays as the tree-walk scheme — the two paths now agree on the same protocol by construction (<code>loop_outcome</code> ≙ <code>loop_step_outcome</code>).</li><li>This is the template for the remaining decline class (<code>eval.ternary</code>, <code>eval.nullish</code>, <code>eval.type-annot</code>, <code>eval.dimension</code>): where a scheme needs a computed value alongside the node input, carry the input through <code>product</code>/<code>pair_tag</code> pairs and let arms project — never substitute a child placeholder where a computed value flows.</li><li><code>match</code>/<code>data</code> are untouched: they still need the <code>desugar.*</code> natives (per-constructor iteration is a macro job, not a scheme shape).</li></ul>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};